<script setup lang="ts">
import InsuranceSelection from './InsuranceSelection.vue';
import type {ApiClient} from '@kuaixie/sdk';
import {useBusinessWorkflow} from './useBusinessWorkflow';
import {watch} from 'vue';
const props=defineProps<{client:ApiClient;flowId:string;context?:Record<string,string>}>();
const p=useBusinessWorkflow(props.client,props.flowId,async(title,content)=>window.confirm(title+'\n\n'+content));
watch(()=>props.context,context=>p.prefill(context??{}),{immediate:true,deep:true,flush:'sync'});
</script>
<template><section class="business-card"><h2>{{$t(p.flow.titleKey)}}</h2><p>{{$t(p.flow.descKey)}}</p><nav class="business-tabs"><button :disabled="p.busy" v-for="(op,i) in p.flow.operations" :key="op.id" :aria-pressed="p.active===i" @click="p.pick(i)">{{p.label(op)}}</button></nav>
 <form @submit.prevent="p.submit"><label v-for="field in p.fields" :key="field.name">{{p.fieldLabel(field.name)}}<select :disabled="p.busy" v-if="field.name==='insuranceChoice'" :value="String(p.form[field.name]??'')" required @change="p.update(field.name,($event.target as HTMLSelectElement).value)"><option disabled value="">{{$t('v15.insurance')}}</option><option value="yes">{{$t('v15.insure')}}</option><option value="waived">{{$t('v15.waive')}}</option></select><input :disabled="p.busy" v-else-if="field.type==='boolean'" type="checkbox" :checked="p.form[field.name]===true" @change="p.update(field.name,($event.target as HTMLInputElement).checked)"/><textarea :disabled="p.busy" v-else-if="p.isLong(field.name)" :value="String(p.form[field.name]??'')" :required="p.required(field.name)" @input="p.update(field.name,($event.target as HTMLTextAreaElement).value)"/><input :disabled="p.busy" v-else :value="String(p.form[field.name]??'')" :type="p.isSecret(field.name)?'password':'text'" :required="p.required(field.name)" @input="p.update(field.name,($event.target as HTMLInputElement).value)"/></label><template v-if="p.current.path==='/rpc/award_pk'&&p.form.insuranceChoice==='yes'"><button type="button" :disabled="p.busy" @click="p.loadInsuranceSubject">{{$t('insurance.loadSubject')}}</button><InsuranceSelection v-if="p.insuranceSubject" :client="client" subject-type="pk_quote" :subject-id="p.insuranceSubject.subjectId" :item-name="p.insuranceSubject.itemName" :declared-value="p.insuranceSubject.declaredValue" @selected="p.update('insuranceQuoteId',$event?.id)"/></template><button :disabled="p.busy">{{$t(p.busy?'fast.submitting':'fast.submit')}}</button></form>
 <p v-if="p.error" role="alert">{{p.error}}</p><div v-if="p.completed" role="status"><strong>{{$t('fast.success')}}</strong><p v-for="pair in p.receipt" :key="pair[0]">{{pair[0]}} · {{pair[1]}}</p></div></section></template>
